mapper.select:
select log_id, channel_id, channel_name, channel_type, event, title, content, status, error, sent_at from itm_notify_log

    and channel_id = #{channelId}
    and event = #{event}
    and status = #{status}
    and date_format(sent_at, '%Y%m%d') >= date_format(#{params.beginTime}, '%Y%m%d')
    and date_format(sent_at, '%Y%m%d') <= date_format(#{params.endTime}, '%Y%m%d')

order by log_id desc
